import logging
from functools import wraps


def log_trigger_operation_data(operation):
    """
    Log input data of operation that is triggered in background and operation's id returned by it.
    NOTE: Every such operation returns OperationStartResponse that contains operation_id attribute.
    """

    @wraps(operation)
    def wrapper(*args, **kwargs):
        """
        :rtype OperationStartResponse
        :return: API response
        """

        logger = logging.getLogger(operation.__module__)
        logger.info('{operation} triggered with args={args}, kwargs={kwargs}'.format(
            operation=operation.__name__,
            args=args[1:],
            kwargs=kwargs)
        )
        response = operation(*args, **kwargs)
        logger.info('operation_id for {operation}: {id}'.format(
            operation=operation.__name__,
            id=response.operation_id)
        )
        return response

    return wrapper


def _bool_to_string_in_server_format(input_bool):
    """ Workaround for cases where server expects boolean value in form of string ('true', 'false'). """
    if input_bool is True:
        return 'true'
    elif input_bool is False:
        return 'false'
    raise TypeError
